import { test, expect } from '@playwright/test';

test.describe('Page Navigation - Jump to Specific Page', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to a page with pagination
    await page.goto('https://example.com/products?page=1');
    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should jump to a specific page using page number input', async ({ page }) => {
    // Find the page number input field
    const pageInput = page.getByLabel(/page number|go to page/i);

    // Enter a specific page number
    await pageInput.fill('5');

    // Submit the form or press Enter
    await pageInput.press('Enter');

    // Wait for navigation to complete
    await page.waitForLoadState('networkidle');

    // Verify that we're on the correct page
    const currentPageIndicator = page.getByText(/page 5|page: 5/i);
    await expect(currentPageIndicator).toBeVisible();

    // Verify URL contains the correct page parameter
    expect(page.url()).toContain('page=5');
  });

  test('should display error message for invalid page number', async ({ page }) => {
    // Find the page number input field
    const pageInput = page.getByLabel(/page number|go to page/i);

    // Enter an invalid page number (e.g., 999 when only 10 pages exist)
    await pageInput.fill('999');

    // Submit the form
    await pageInput.press('Enter');

    // Wait for response
    await page.waitForLoadState('networkidle');

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid page|page not found|out of range/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should navigate to page using jump button', async ({ page }) => {
    // Find the page number input field
    const pageInput = page.getByLabel(/page number|go to page/i);

    // Enter a page number
    await pageInput.fill('3');

    // Find and click the jump/go button
    const jumpButton = page.getByRole('button', { name: /jump|go|navigate/i });
    await jumpButton.click();

    // Wait for navigation
    await page.waitForLoadState('networkidle');

    // Verify we're on the correct page
    const pageIndicator = page.getByText(/page 3|page: 3/i);
    await expect(pageIndicator).toBeVisible();
  });

  test('should clear input field after successful navigation', async ({ page }) => {
    // Find the page number input field
    const pageInput = page.getByLabel(/page number|go to page/i);

    // Enter a page number
    await pageInput.fill('2');

    // Submit
    await pageInput.press('Enter');

    // Wait for navigation
    await page.waitForLoadState('networkidle');

    // Verify input field is cleared or reset
    await expect(pageInput).toHaveValue('');
  });

  test('should maintain other filters when jumping to a page', async ({ page }) => {
    // Navigate to a page with filters
    await page.goto('https://example.com/products?category=electronics&sort=price&page=1');

    // Find the page number input
    const pageInput = page.getByLabel(/page number|go to page/i);

    // Jump to page 4
    await pageInput.fill('4');
    await pageInput.press('Enter');

    // Wait for navigation
    await page.waitForLoadState('networkidle');

    // Verify that filters are maintained in the URL
    expect(page.url()).toContain('category=electronics');
    expect(page.url()).toContain('sort=price');
    expect(page.url()).toContain('page=4');
  });
});
